    "text:Which tested object sank?": "/audio/4b97dcf3d459ecd5464da09c.mp3",
    "text:The solid steel key sank.": "/audio/4abcf1443d5bfd6c257344f7.mp3",
    "text:The answer is Steel key. Thank you for trying. Look at the key at the bottom of the water.": "/audio/71fd48ea009be328108de17d.mp3",
    "text:The answer is Facing the Sun. Thank you for trying. The Sun lights the side facing it. The other side is dark.": "/audio/1cf31a3ace12791f6ac856b2.mp3",
    "text:The answer is Steel key. The solid steel key sank.": "/audio/4172fc9ad7d7811d5da7f87d.mp3",
